#!/usr/bin/env python
"""Consolidate all cross-specialist direction results into one table."""
import json
import sys
import pandas as pd
from pathlib import Path

PROJECT = Path(__file__).resolve().parent.parent.parent
sys.path.insert(0, str(PROJECT / "scripts"))
from _config import RESULT_ROOT, DATA_ROOT
RESULTS = RESULT_ROOT

# Full-gene perturb-seq results: prefer results/ (regenerated by the eval
# scripts); optionally fall back to pre-computed copies in a local sibling
# directory (BoYueGRN-figures/data/benchmark/ablation_controls/) if present.
BUNDLED_AB = PROJECT.parent / "BoYueGRN-figures" / "data" / "benchmark" / "ablation_controls"

def _load_json(name, results_subdir):
    p = RESULTS / results_subdir / name
    if not p.exists():
        p = BUNDLED_AB / name
    return json.load(open(p))

rows = []

# ===========================================================
# 1. Synthetic (G=200, single window)
# ===========================================================
syn = json.load(open(RESULTS / "1_synthetic" / "synthetic_cross_specialist.json"))
rows.append({
    'dataset': 'Synthetic',
    'source': 'SCM',
    'coverage': 'G=200',
    'nt_on_nontf': syn['NT_on_tf_non_tf'],
    'nt_on_tftf': syn['NT_on_tf_tf'],
    'tt_on_nontf': syn['TT_on_tf_non_tf'],
    'tt_on_tftf': syn['TT_on_tf_tf'],
    'nt_all': syn['NT_on_all'],
    'tt_all': syn['TT_on_all'],
    'matched_all': (syn['NT_on_tf_non_tf'] + syn['TT_on_tf_tf']) / 2,  # rough matched
    'n_eval': None,
    'n_windows': 1,
})

# ===========================================================
# 2. BEELINE (full-gene multi-window)
# ===========================================================
bl = pd.read_csv(RESULTS / "3_full_gene" / "beeline_cross_specialist.csv")
for _, r in bl.iterrows():
    rows.append({
        'dataset': r['dataset'],
        'source': 'BEELINE',
        'coverage': 'full-gene',
        'nt_on_nontf': r['nt_on_nontf'],
        'nt_on_tftf': r['nt_on_tftf'],
        'tt_on_nontf': r['tt_on_nontf'],
        'tt_on_tftf': r['tt_on_tftf'],
        'nt_all': r['nt_all'],
        'tt_all': r['tt_all'],
        'matched_all': r['matched_all'],
        'n_eval': r['n_eval'],
        'n_windows': r['n_windows'],
    })

# ===========================================================
# 3. HCT116 G=200
# ===========================================================
hct = json.load(open(RESULTS / "3_full_gene" / "hct116_g200_cross_specialist.json"))
rows.append({
    'dataset': 'HCT116',
    'source': 'Perturb-seq',
    'coverage': 'G=200',
    'nt_on_nontf': hct['nt_on_nontf'],
    'nt_on_tftf': hct['nt_on_tftf'],
    'tt_on_nontf': hct['tt_on_nontf'],
    'tt_on_tftf': hct['tt_on_tftf'],
    'nt_all': hct['nt_all'],
    'tt_all': hct['tt_all'],
    'matched_all': hct['matched_all'],
    'n_eval': hct['n_eval'],
    'n_windows': 1,
})

# ===========================================================
# 4. K562 G=200
# ===========================================================
k56 = json.load(open(RESULTS / "3_full_gene" / "k562_g200_cross_specialist.json"))
rows.append({
    'dataset': 'K562',
    'source': 'Perturb-seq',
    'coverage': 'G=200',
    'nt_on_nontf': k56['nt_on_nontf'],
    'nt_on_tftf': k56['nt_on_tftf'],
    'tt_on_nontf': k56['tt_on_nontf'],
    'tt_on_tftf': k56['tt_on_tftf'],
    'nt_all': k56['nt_all'],
    'tt_all': k56['tt_all'],
    'matched_all': k56['matched_all'],
    'n_eval': k56['n_eval'],
    'n_windows': 1,
})

# ===========================================================
# 5. HCT116 full-gene
# ===========================================================
hct_full = _load_json("hct116_cross_specialist.json", "3_full_gene")
rows.append({
    'dataset': 'HCT116',
    'source': 'Perturb-seq',
    'coverage': 'full-gene',
    'nt_on_nontf': hct_full['nt_on_nontf_all'],
    'nt_on_tftf': hct_full['nt_on_tftf_all'],
    'tt_on_nontf': hct_full['tt_on_nontf_all'],
    'tt_on_tftf': hct_full['tt_on_tftf_all'],
    'nt_all': hct_full['nt_only_all_diracc'],
    'tt_all': hct_full['tt_only_all_diracc'],
    'matched_all': hct_full['matched_all_diracc'],
    'n_eval': None,
    'n_windows': hct_full['n_windows'],
})

# ===========================================================
# 6. K562 full-gene
# ===========================================================
k56_full = _load_json("k562_multiwindow_results.json", "3_full_gene")
rows.append({
    'dataset': 'K562',
    'source': 'Perturb-seq',
    'coverage': 'full-gene',
    'nt_on_nontf': k56_full['nt_on_nontf_all'],
    'nt_on_tftf': k56_full['nt_on_tftf_all'],
    'tt_on_nontf': k56_full['tt_on_nontf_all'],
    'tt_on_tftf': k56_full['tt_on_tftf_all'],
    'nt_all': k56_full['nt_only_all_diracc'],
    'tt_all': k56_full['tt_only_all_diracc'],
    'matched_all': k56_full['matched_all_diracc'],
    'n_eval': None,
    'n_windows': k56_full['n_windows'],
})

# ===========================================================
# Save
# ===========================================================
df = pd.DataFrame(rows)
df = df.sort_values(['source', 'dataset', 'coverage']).reset_index(drop=True)

print("=" * 120)
print("CROSS-SPECIALIST DIRECTION ACCURACY — ALL DATASETS")
print("=" * 120)
print(f"\n{'Dataset':<12s} {'Source':<12s} {'Cov':<10s} "
      f"{'NT->nonTF':>9s} {'NT->TF':>9s} {'TT->nonTF':>9s} {'TT->TF':>9s} "
      f"{'NT all':>8s} {'TT all':>8s} {'Match':>8s} {'n_eval':>8s}")
print("-" * 120)
for _, r in df.iterrows():
    print(f"{r['dataset']:<12s} {r['source']:<12s} {r['coverage']:<10s} "
          f"{r['nt_on_nontf']:>9.4f} {r['nt_on_tftf']:>9.4f} {r['tt_on_nontf']:>9.4f} {r['tt_on_tftf']:>9.4f} "
          f"{r['nt_all']:>8.4f} {r['tt_all']:>8.4f} {r['matched_all']:>8.4f} "
          f"{r['n_eval'] if pd.notna(r['n_eval']) else '—':>8}")

out_path = RESULTS / "3_full_gene" / "cross_specialist_consolidated.csv"
df.to_csv(out_path, index=False)
print(f"\nSaved: {out_path}")

# Summary by coverage
print("\n" + "=" * 60)
print("SUMMARY BY COVERAGE")
print("=" * 60)
for cov in ['G=200', 'full-gene']:
    sub = df[df['coverage'] == cov]
    print(f"\n{cov}:")
    print(f"  Mean NT->nonTF: {sub['nt_on_nontf'].mean():.4f}")
    print(f"  Mean TT->TF:    {sub['tt_on_tftf'].mean():.4f}")
    print(f"  Mean NT all:   {sub['nt_all'].mean():.4f}")
    print(f"  Mean TT all:   {sub['tt_all'].mean():.4f}")
    print(f"  Mean Matched:  {sub['matched_all'].mean():.4f}")
